#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    vector<long long> allowed = a;
    sort(allowed.begin(), allowed.end());
    allowed.erase(unique(allowed.begin(), allowed.end()), allowed.end());
    // distinct ORs of subarrays ending here with their counts, shortest first;
    // ORs only grow as a subarray extends left, so equal values are adjacent
    vector<pair<long long, long long>> previous, current;
    long long answer = 0;
    for (long long value : a) {
        current.assign(1, {value, 1});
        for (auto &[old, count] : previous) {
            long long key = old | value;
            if (current.back().first == key) current.back().second += count;
            else current.push_back({key, count});
        }
        for (auto &[key, count] : current)
            if (binary_search(allowed.begin(), allowed.end(), key)) answer += count;
        swap(previous, current);
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] allowed = a.clone();
        Arrays.sort(allowed);
        // distinct ORs of subarrays ending here with their counts, shortest first;
        // ORs only grow as a subarray extends left, so equal values are adjacent
        long[] prevKey = new long[64], prevCount = new long[64], curKey = new long[64], curCount = new long[64];
        int prevSize = 0;
        long answer = 0;
        for (long value : a) {
            int size = 0;
            curKey[size] = value;
            curCount[size++] = 1;
            for (int t = 0; t < prevSize; t++) {
                long key = prevKey[t] | value;
                if (curKey[size - 1] == key) curCount[size - 1] += prevCount[t];
                else {
                    curKey[size] = key;
                    curCount[size++] = prevCount[t];
                }
            }
            for (int t = 0; t < size; t++) if (Arrays.binarySearch(allowed, curKey[t]) >= 0) answer += curCount[t];
            long[] swapKey = prevKey, swapCount = prevCount;
            prevKey = curKey;
            prevCount = curCount;
            curKey = swapKey;
            curCount = swapCount;
            prevSize = size;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a := make([]int, n)
	for i := range a {
		a[i] = next()
	}
	allowed := append([]int(nil), a...)
	sort.Ints(allowed)
	type state struct{ key, count int }
	// distinct ORs of subarrays ending here with their counts, shortest first;
	// ORs only grow as a subarray extends left, so equal values are adjacent
	var previous, current []state
	answer := 0
	for _, value := range a {
		current = append(current[:0], state{value, 1})
		for _, s := range previous {
			key := s.key | value
			if current[len(current)-1].key == key {
				current[len(current)-1].count += s.count
			} else {
				current = append(current, state{key, s.count})
			}
		}
		for _, s := range current {
			if i := sort.SearchInts(allowed, s.key); i < n && allowed[i] == s.key {
				answer += s.count
			}
		}
		previous, current = current, previous
	}
	fmt.Println(answer)
}
